<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,computed} from 'vue'
import * as T from 'three'
import {createDetailedShip,EMPTY_ASSEMBLY} from './workshopModel'
import {riverMaterial} from '../v13/riverSurface'
import {riverPoint,fleetSlots,riverFeedback} from '../v13/riverNavigation'
import {riverStart,riverProgress,riverSafe} from './experience'
type Snapshot={position:number;river_x:number;river_z:number;placed:boolean}
const props=defineProps<{mode:string;motion:boolean;freeExploration?:boolean;initial?:Snapshot}>(),emit=defineEmits<{complete:[payload:Snapshot];change:[payload:Snapshot]}>()
const start=riverStart(props.mode),host=ref<HTMLDivElement>(),placed=ref(props.initial?.placed||false),moving=ref(false),xpos=ref(props.initial?.river_x??start.x),zpos=ref(props.initial?.river_z??start.z),fault=ref(false),closeView=ref(false),bankLabel=ref<HTMLDivElement>(),lineLabel=ref<HTMLDivElement>(),tailLabel=ref<HTMLParagraphElement>()
const rescue=computed(()=>props.mode==='rescue'),value=computed(()=>riverProgress(props.mode,zpos.value)),safe=computed(()=>riverSafe(props.mode,xpos.value,zpos.value)),feedback=computed(()=>props.freeExploration&&props.mode!=='rescue'?(value.value>65?(props.mode==='command'?'寨灯渐远，哨艇已探入更深的江面。':'寨楼渐近，草把也进了对岸的视线。'):(props.mode==='command'?'哨艇仍望得见寨门，正沿水线探查。':'船队停在较宽的水面，后船正逐次跟上。')):riverFeedback(props.mode,xpos.value,zpos.value).message)
let renderer:T.WebGLRenderer,scene:T.Scene,camera:T.PerspectiveCamera,frame=0,resize:ResizeObserver,leader:T.Group;let target=new T.Vector3(xpos.value,0,zpos.value),drag=false
const fleet:T.Group[]=[]
function snapshot():Snapshot{return {position:value.value,river_x:xpos.value,river_z:zpos.value,placed:placed.value}}
function locate(x:number,z:number){const p=riverPoint(x,z);xpos.value=p.x;zpos.value=p.z;target.set(xpos.value,0,zpos.value);placed.value=true;moving.value=!fault.value;emit('change',snapshot())}
function keys(e:KeyboardEvent){if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();locate(xpos.value+(e.key==='ArrowRight'?2:e.key==='ArrowLeft'?-2:0),zpos.value+(e.key==='ArrowDown'?2:e.key==='ArrowUp'?-2:0))}
onMounted(()=>{try{scene=new T.Scene();scene.background=new T.Color('#102534');scene.fog=new T.FogExp2('#182e3d',.017);camera=new T.PerspectiveCamera(45,1,.1,200);camera.position.set(0,36,35);camera.lookAt(0,0,3)
renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.25));renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;Object.assign(renderer.domElement.style,{display:'block',position:'absolute',inset:'0',width:'100%',height:'100%'});host.value!.append(renderer.domElement)
scene.add(new T.HemisphereLight(0xc4dbe8,0x263c49,3.2));const light=new T.DirectionalLight(0xffd39a,3.4);light.position.set(-4,14,10);scene.add(light)
const water=new T.Mesh(new T.PlaneGeometry(160,160),riverMaterial());water.rotation.x=-Math.PI/2;water.position.y=-.16;scene.add(water)
const riverLines=new T.Group();for(let i=0;i<26;i++){const points=[];for(let j=0;j<30;j++)points.push(new T.Vector3(-35+j*2.4,-.12,-36+i*3+.18*Math.sin(j*.8+i)));riverLines.add(new T.Line(new T.BufferGeometry().setFromPoints(points),new T.LineBasicMaterial({color:0x6d9eac,transparent:true,opacity:.15})))}scene.add(riverLines)
const lineZ=props.mode==='command'?.35:-5.35,boundary=new T.Line(new T.BufferGeometry().setFromPoints([new T.Vector3(-22,0,lineZ),new T.Vector3(22,0,lineZ)]),new T.LineDashedMaterial({color:0xc49a6e,dashSize:.7,gapSize:.5}));boundary.computeLineDistances();scene.add(boundary)
// The far bank occupies the same world coordinates as the water and ships.
const bank=new T.Mesh(new T.BoxGeometry(60,1.2,6),new T.MeshStandardMaterial({color:0x26332f,roughness:1}));bank.position.set(0,.3,-24);scene.add(bank)
for(let i=0;i<38;i++){const palisade=new T.Mesh(new T.CylinderGeometry(.14,.2,2.8,5),new T.MeshStandardMaterial({color:0x433a2c,roughness:1}));palisade.position.set(-27+i*1.5,1.8,-20.9);scene.add(palisade)}
for(let i=0;i<18;i++){const rock=new T.Mesh(new T.DodecahedronGeometry(.7+(i%4)*.18,0),new T.MeshStandardMaterial({color:0x3b4945,roughness:1}));rock.position.set(-28+i*3.2,.4,-20.7+(i%3)*.22);rock.scale.set(1.4,.5,.7);rock.rotation.y=i*.8;scene.add(rock)}
const timber=new T.MeshStandardMaterial({color:0x65513a,roughness:.95}),roofMat=new T.MeshStandardMaterial({color:0x393a36,roughness:1});
for(const x of [-14,-5,5,14]){const tower=new T.Group();for(const dx of [-1,1])for(const dz of [-1,1]){const post=new T.Mesh(new T.BoxGeometry(.18,4.5,.18),timber);post.position.set(dx,2.1,dz);tower.add(post)}const deck=new T.Mesh(new T.BoxGeometry(2.8,.18,2.8),timber);deck.position.y=3.1;tower.add(deck);const roof=new T.Mesh(new T.ConeGeometry(2.2,1.1,4),roofMat);roof.position.y=5.1;roof.rotation.y=Math.PI/4;tower.add(roof);for(const y of [1.2,2.8,3.8]){const rail=new T.Mesh(new T.BoxGeometry(2.3,.12,.14),timber);rail.position.set(0,y,1.05);tower.add(rail)}for(const dx of [-.7,0,.7]){const rail=new T.Mesh(new T.BoxGeometry(.08,.75,.08),timber);rail.position.set(dx,3.5,1.1);tower.add(rail)}tower.position.set(x,0,-22);scene.add(tower);const fire=new T.Mesh(new T.SphereGeometry(.18,8,6),new T.MeshBasicMaterial({color:0xffbd65}));fire.position.set(x,3.7,-20.7);scene.add(fire);const glow=new T.PointLight(0xffb761,8,13,2);glow.position.copy(fire.position);scene.add(glow)}
leader=createDetailedShip(props.mode==='command'?{...EMPTY_ASSEMBLY,clear_aisle:true}:undefined);leader.scale.setScalar(props.mode==='position'?.56:.85);leader.position.copy(target);if(props.mode==='command')leader.rotation.y=Math.PI;scene.add(leader);fleet.push(leader)
if(rescue.value){const tail=createDetailedShip();tail.scale.setScalar(.85);tail.position.set(6,0,4);tail.rotation.y=.22;scene.add(tail)}
else if(props.mode!=='command'){for(let i=1;i<20;i++){const boat=leader.clone(true);boat.scale.setScalar(.56);scene.add(boat);fleet.push(boat)}}
for(const boat of fleet){boat.traverse((o:any)=>{if(!o.material)return;const mats=Array.isArray(o.material)?o.material:[o.material];for(const m of mats){if(m.color&&o.parent?.name==='hull-strakes')m.color.setHex(0xd4ad74);if(m.color&&o.parent?.name?.includes('straw'))m.color.setHex(0xd5bf80);if(m.color&&o.parent?.name==='cloth')m.color.setHex(0x568b94);if(m.emissiveIntensity)m.emissiveIntensity=2.5}})}
// The open starboard lane is real world space, beyond all five abreast slots.
const lane=new T.Mesh(new T.PlaneGeometry(2.2,20),new T.MeshBasicMaterial({color:0x76a6a6,transparent:true,opacity:.12,depthWrite:false}));lane.rotation.x=-Math.PI/2;lane.position.set(target.x+8.2,-.07,target.z+(props.mode==='command'?-7:7));scene.add(lane)
const routeGeo=new T.BufferGeometry().setFromPoints([new T.Vector3(start.x,.06,start.z),target.clone().setY(.06)]),route=new T.Line(routeGeo,new T.LineDashedMaterial({color:0xb8c7ba,dashSize:.45,gapSize:.32,transparent:true,opacity:.5}));route.computeLineDistances();scene.add(route)
const wakes=new T.Group();for(let i=0;i<(props.mode==='position'?20:1);i++){const wake=new T.Line(new T.BufferGeometry().setFromPoints([new T.Vector3(-.5,0,1.5),new T.Vector3(-.85,0,3),new T.Vector3(.85,0,3),new T.Vector3(.5,0,1.5)]),new T.LineBasicMaterial({color:0x83a8ad,transparent:true,opacity:.18}));wakes.add(wake)}scene.add(wakes)
const ribbon=new T.Mesh(new T.PlaneGeometry(1,1),new T.MeshBasicMaterial({color:0xd1c298,transparent:true,opacity:.12,depthWrite:false}));ribbon.rotation.x=-Math.PI/2;scene.add(ribbon)
const buoy=new T.Group(),pole=new T.Mesh(new T.CylinderGeometry(.045,.065,1.3,6),new T.MeshStandardMaterial({color:0xd1b77f,roughness:.9})),lantern=new T.Mesh(new T.SphereGeometry(.18,10,8),new T.MeshBasicMaterial({color:0xffd18a}));pole.position.y=.65;lantern.position.y=1.4;buoy.add(pole,lantern);scene.add(buoy)
const slots=fleetSlots(),cameraAim=new T.Vector3(0,0,3)
const marker=new T.Mesh(new T.RingGeometry(1.25,1.38,64),new T.MeshBasicMaterial({color:0xe1c484,side:T.DoubleSide,transparent:true,opacity:.8}));marker.rotation.x=-Math.PI/2;marker.position.copy(target);marker.position.y=.02;scene.add(marker)
const ray=new T.Raycaster(),pointer=new T.Vector2(),plane=new T.Plane(new T.Vector3(0,1,0),0)
function choose(e:PointerEvent){const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);const p=new T.Vector3();if(ray.ray.intersectPlane(plane,p))locate(p.x,p.z)}
renderer.domElement.style.touchAction='none';renderer.domElement.addEventListener('pointerdown',e=>{drag=true;renderer.domElement.setPointerCapture(e.pointerId);choose(e)});renderer.domElement.addEventListener('pointermove',e=>{if(drag)choose(e)});renderer.domElement.addEventListener('pointerup',()=>drag=false);renderer.domElement.addEventListener('pointercancel',()=>drag=false)
let width=0,height=0;const size=()=>{if(!host.value)return;const w=host.value.clientWidth,h=host.value.clientHeight;if(w<1||h<1||(w===width&&h===height))return;width=w;height=h;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()};resize=new ResizeObserver(size);resize.observe(host.value!);size()
let last=0;const draw=(ms:number)=>{frame=requestAnimationFrame(draw);const dt=Math.min(.1,(ms-last)/1000);last=ms;const k=props.motion?1-Math.exp(-dt*3):1;leader.position.lerp(target,k);moving.value=leader.position.distanceTo(target)>.05;marker.position.set(target.x,.02,target.z);buoy.position.set(target.x,.03,target.z);buoy.visible=placed.value;const routeLength=Math.hypot(target.x-start.x,target.z-start.z);ribbon.visible=placed.value&&routeLength>.1;ribbon.scale.set(.8,routeLength,1);ribbon.position.set((start.x+target.x)/2,-.05,(start.z+target.z)/2);ribbon.rotation.z=Math.atan2(target.x-start.x,target.z-start.z);const desiredCamera=closeView.value?new T.Vector3(leader.position.x+7,10,leader.position.z+12):new T.Vector3(leader.position.x+1,36,35),desiredAim=closeView.value?new T.Vector3(leader.position.x,1,leader.position.z+1):new T.Vector3(leader.position.x+1,0,3);camera.position.lerp(desiredCamera,props.motion?Math.min(1,dt*4):1);cameraAim.lerp(desiredAim,props.motion?Math.min(1,dt*4):1);camera.lookAt(cameraAim);marker.material.color.setHex(props.freeExploration?0xe2c284:safe.value?0xe2c284:0xd08469);fleet.slice(1).forEach((b,i)=>{const slot=slots[i+1];b.position.set(leader.position.x+slot.x,leader.position.y,leader.position.z+slot.z)});lane.position.set(leader.position.x+8.2,-.07,leader.position.z+(props.mode==='command'?-7:7));routeGeo.setFromPoints([new T.Vector3(start.x,.06,start.z),new T.Vector3(target.x,.06,target.z)]);route.computeLineDistances();wakes.children.forEach((w,i)=>{const b=fleet[i]||leader;w.position.set(b.position.x,-.04,b.position.z)});water.material.uniforms.time.value=props.motion?ms*.001:0;if(props.motion)riverLines.position.z=Math.sin(ms*.0004)*.35;for(const [el,p] of [[bankLabel.value,new T.Vector3(leader.position.x+14,3,-22)],[lineLabel.value,new T.Vector3(leader.position.x+16,0,lineZ)],[tailLabel.value,new T.Vector3(6,1,4)]] as const){if(!el)continue;const v=p.project(camera);el.style.left=Math.max(20,Math.min(width-145,(v.x*.5+.5)*width))+'px';el.style.top=Math.max(80,Math.min(height-180,(-v.y*.5+.5)*height+14))+'px'}renderer.render(scene,camera)};frame=requestAnimationFrame(draw)
}catch{fault.value=true}})
onBeforeUnmount(()=>{cancelAnimationFrame(frame);resize?.disconnect();const gs=new Set<T.BufferGeometry>(),ms=new Set<T.Material>(),textures=new Set<T.Texture>();scene?.traverse((o:any)=>{if(o.isInstancedMesh)o.dispose();if(o.geometry)gs.add(o.geometry);if(o.material)for(const m of Array.isArray(o.material)?o.material:[o.material])ms.add(m)});gs.forEach(g=>g.dispose());ms.forEach(m=>{for(const value of Object.values(m))if(value instanceof T.Texture)textures.add(value);m.dispose()});textures.forEach(t=>t.dispose());renderer?.dispose();renderer?.forceContextLoss();renderer?.domElement.remove()})
</script>
<template><section class="river-maneuver"><div ref="host" class="river-world" tabindex="0" aria-label="江面实际船只布位，可点击水面或方向键移动" @keydown="keys"></div><header><span>{{rescue?'接应不是一句口号':'近与远，都有后续'}}</span><h2>{{rescue?'把末船带回来':mode==='command'?'哨艇探到哪里':'把船带到你选的水面'}}</h2><p>{{rescue?'末船偏在右后方。把接应船移到它外侧，才接得上缆。':mode==='command'?(freeExploration?'哨艇从北岸出发。选定探查的位置，再决定是向前、分探，还是收队。':'身后灯火是曹寨。哨艇从北岸出发，向江心探明敌情；不要越过虚线追深。'):(freeExploration?'前方是曹寨。拖动江面安排船位：停在江心，或带船更近些。':'前方灯火是曹寨。把船停在虚线外侧，别堵进寨口。')}}</p></header><button class="river-view" :aria-pressed="closeView" @click="closeView=!closeView">{{closeView?'俯看全队 ↗':'走近领船 ↘'}}</button><div class="river-view-caption">{{closeView?'船边看航标 · 拖动水面改位':'登高看全队 · 留右侧回转水道'}}</div><div ref="bankLabel" v-show="!closeView" class="bank-label">北岸 · 曹寨</div><div ref="lineLabel" v-show="!closeView" class="waterline-label" :style="mode==='command'?{top:'57%'}:{}">警戒水线</div><p ref="tailLabel" v-if="rescue&&!closeView" class="tail-label">末船 · 右后方</p><div class="river-controls"><p class="order-status" aria-live="polite">{{placed?(moving?'领船移向航标，后队随行……':feedback):'点水面立航标，或拖动改航线。方向键每次移两步。'}}</p><small>○ 领船航标　┄ 来时航迹　▯ {{mode==='command'?'回寨水道':'回转水道'}}</small><div class="helm-pad" aria-label="移船方向"><button aria-label="向左水道移动" @click="locate(xpos-2,zpos)">← 左水道</button><button aria-label="向北岸移动" @click="locate(xpos,zpos-2)">↑ 北岸</button><button aria-label="向江心移动" @click="locate(xpos,zpos+2)">↓ 江心</button><button aria-label="向右水道移动" @click="locate(xpos+2,zpos)">右水道 →</button></div><small v-if="fault">三维画面未能打开，可用方向按钮安排位置。</small></div><button class="gold river-apply" :disabled="!placed||moving" @click="emit('complete',snapshot())">把这个位置交给操舟军士</button></section></template>
<style scoped>.river-maneuver,.river-world{position:absolute;inset:0}.river-maneuver{overflow:hidden;background:#102534}.river-world{overflow:hidden}.river-world :deep(canvas){display:block;width:100%;height:100%}.river-world canvas{display:block}.river-view{position:absolute;right:4%;top:14%;color:#ead5a9;background:#0d2632df;border:1px solid #a1a894;padding:12px 18px;cursor:pointer;font:14px SimSun}.river-view:focus-visible{outline:2px solid #efce90}.river-view-caption{position:absolute;right:4%;top:21%;font:11px SimSun;color:#b2c6c5;pointer-events:none}.river-world:focus{outline:1px solid #c0a476;outline-offset:-4px}header{position:absolute;pointer-events:none;top:8%;left:4%;max-width:350px;text-shadow:0 3px 8px #000}header span{font-size:12px;letter-spacing:.15em;color:#d5b779}header h2{font:30px SimSun;color:#eee0c6;margin:15px 0}header p{font-size:14px;line-height:1.7;color:#d3dfe4;max-width:360px}.bank-label,.waterline-label,.tail-label{position:absolute;pointer-events:none;color:#d4bc84;font-size:12px;text-shadow:0 2px 5px #000}.bank-label{left:65%;top:16%}.waterline-label{left:78%;top:47%}.tail-label{left:59%;top:66%}.river-controls{position:absolute;bottom:4%;left:4%;background:linear-gradient(90deg,#051723ed,#051723aa);border-left:2px solid #9db3af;padding:12px 16px;max-width:min(310px,33vw)}.river-controls small{font-size:11px;color:#a6bdc2}.river-controls .helm-pad{display:flex;gap:8px;flex-wrap:wrap}.river-controls button{cursor:pointer;background:transparent;color:#e5d7b8;border:0;font:12px SimSun}.river-controls button:focus-visible{outline:2px solid #e2c284}.river-apply{cursor:pointer;border:1px solid #bda36e;background:#dcc89b;color:#172d34;padding:14px 20px;font:14px SimSun}.river-controls p{font-size:13px;color:#dce4e5}.river-controls button{margin:4px 8px 0 0;border-bottom:1px solid #be9c68;padding:10px}.river-apply{position:absolute;right:4%;bottom:4%}.river-apply:disabled{opacity:.4}@media(max-width:800px){header{max-width:70%;top:8%}header p{font-size:12px;max-width:300px}header h2{font-size:26px}.river-controls{bottom:15%;left:4%;right:4%;max-width:none;font-size:11px}.river-apply{bottom:5%;right:4%}.river-controls button{padding:7px}.tail-label{top:58%}}</style>


